head.b:skin:
/* --- SOLID UI & VARIABLES --- */
:root {
    --bg-body: #f8f9fa;
    --bg-card: #ffffff;
    --bg-header: #ffffff;
    --text-main: #111111;
    --text-muted: #666666;
    --accent: #222222;
    --accent-hover: #000000;
    --danger: #dc3545;
    --warning: #ffc107;
    --success: #198754;
    --font-main: 'Inter', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-body); font-family: var(--font-main); color: var(--text-main); padding-top: 80px; }

/* NO BLUR POLICY */
header, .modal-content, .offcanvas { background: var(--bg-card) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }

/* Layout */
.navbar { background: var(--bg-header); border-bottom: 1px solid #eee; padding: 1rem 0; position: fixed; top: 0; width: 100%; z-index: 1000; }
.product-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 20px; }

/* Cards */
.card-product { border: 1px solid #eee; transition: transform 0.2s; position: relative; background: var(--bg-card); overflow: hidden; }
.card-product:hover { transform: translateY(-2px); box-shadow: 0 5px 15px rgba(0,0,0,0.05); }
.card-img-wrapper { position: relative; padding-top: 125%; /* 4:5 Aspect Ratio for Fashion */ overflow: hidden; background: #f0f0f0; }
.card-img-wrapper img { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; transition: opacity 0.3s ease; }
.card-actions { position: absolute; bottom: -50px; left: 0; width: 100%; display: flex; justify-content: center; gap: 10px; padding: 10px; background: rgba(255,255,255,0.9); transition: bottom 0.3s; }
.card-product:hover .card-actions { bottom: 0; }

/* Badges */
.badge-stock { position: absolute; top: 10px; left: 10px; z-index: 2; font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; font-weight: 600; }
.bg-low-stock { background-color: var(--warning); color: #000; }
.bg-sold-out { background-color: var(--danger); color: #fff; }

/* Skeletons */
.skeleton { background: #e0e0e0; border-radius: 4px; animation: pulse 1.5s infinite; }
@keyframes pulse { 0% { opacity: 0.6; } 50% { opacity: 1; } 100% { opacity: 0.6; } }

/* Fly-to-Cart Element */
.fly-img { position: fixed; z-index: 9999; transition: all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius: 50%; pointer-events: none; box-shadow: 0 5px 15px rgba(0,0,0,0.2); }

/* Utilities */
.cursor-pointer { cursor: pointer; }
.text-truncate-2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.hide { display: none !important; }

/* Scroll Sentinel */
#scroll-sentinel { height: 50px; display: flex; align-items: center; justify-content: center; margin: 20px 0; }

/* Toast Container */
.toast-container { position: fixed; bottom: 20px; right: 20px; z-index: 1060; }

body.script:
//

/**
 * @namespace App
 * @description Main Application Module for Aji Shop Casa
 */
const App = {
    State: {
        products: [],     // All fetched products
        displayed: 0,     // How many items are currently in DOM
        batchSize: 20,    // Virtual scroll batch size
        cart: [],         // Cart items
        wishlist: [],     // Wishlist indices
        currency: '$',
        currentProduct: null // For QuickView
    },

    /**
     * @namespace App.Utils
     * @description Utility functions for sanitization and formatting
     */
    Utils: {
        /**
         * @description Escapes quotes and backticks to prevent HTML injection
         * @param {string} str - Input string
         * @returns {string} Sanitized string
         */
        safeStr: (str) => {
            if (!str) return '';
            return str.toString().replace(/`/g, '&#96;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        },

        /**
         * @description Formats currency
         * @param {number} num - Price
         * @returns {string} Formatted string
         */
        formatCurrency: (num) => {
            return App.State.currency + parseFloat(num).toFixed(2);
        },

        /**
         * @description Generates a consistent random image based on seed
         * @param {string} seed - Unique ID
         * @param {number} w - Width
         * @param {number} h - Height
         * @returns {string} URL
         */
        getPlaceholder: (seed, w, h) => `https://picsum.photos/seed/${seed}/${w}/${h}.jpg`
    },

    /**
     * @namespace App.Seo
     * @description Handles Schema.org injection
     */
    Seo: {
        /**
         * @description Injects JSON-LD schema for a product
         * @param {Object} product - Product object
         */
        injectSchema: (product) => {
            const schema = {
                "@context": "https://schema.org/",
                "@type": "Product",
                "name": product.title,
                "image": product.image,
                "description": product.description,
                "offers": {
                    "@type": "Offer",
                    "priceCurrency": "USD",
                    "price": product.price,
                    "availability": product.stock > 0 ? "https://schema.org/InStock" : "https://schema.org/OutOfStock"
                }
            };

            // Remove old schema if exists
            const oldSchema = document.getElementById('product-schema');
            if (oldSchema) oldSchema.remove();

            const script = document.createElement('script');
            script.type = 'application/ld+json';
            script.id = 'product-schema';
            script.text = JSON.stringify(schema);
            document.head.appendChild(script);
        }
    },

    /**
     * @namespace App.UI
     * @description Handles UI interactions, Toasts, and DOM updates
     */
    UI: {
        toast: (msg, type = 'success') => {
            const bgClass = type === 'success' ? 'text-bg-success' : 'text-bg-danger';
            const html = `
                <div class="toast align-items-center ${bgClass} border-0 show" role="alert">
                    <div class="d-flex">
                        <div class="toast-body">${msg}</div>
                        <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button>
                    </div>
                </div>`;
            const container = document.getElementById('toast-container');
            const el = document.createElement('div');
            el.innerHTML = html;
            container.appendChild(el.firstElementChild);
            setTimeout(() => { container.innerHTML = ''; }, 3000);
        },

        toggleCart: () => {
            const el = document.getElementById('cartOffcanvas');
            const bsOffcanvas = new bootstrap.Offcanvas(el);
            bsOffcanvas.toggle();
        },

        /**
         * @description Triggers Fly-to-Cart animation
         * @param {HTMLElement} sourceImg - The image element clicked
         */
        flyToCart: (sourceImg) => {
            const cartIcon = document.querySelector('.bi-bag');
            const rect = sourceImg.getBoundingClientRect();
            const cartRect = cartIcon.getBoundingClientRect();

            const flyImg = sourceImg.cloneNode();
            flyImg.classList.add('fly-img');
            flyImg.style.width = rect.width + 'px';
            flyImg.style.height = rect.height + 'px';
            flyImg.style.top = rect.top + 'px';
            flyImg.style.left = rect.left + 'px';

            document.body.appendChild(flyImg);

            // Force reflow
            void flyImg.offsetWidth; 

            flyImg.style.top = cartRect.top + 'px';
            flyImg.style.left = cartRect.left + 'px';
            flyImg.style.width = '20px';
            flyImg.style.height = '20px';
            flyImg.style.opacity = '0.5';

            setTimeout(() => {
                flyImg.remove();
                App.UI.updateCartCount();
            }, 800);
        },

        updateCartCount: () => {
            const count = App.State.cart.reduce((acc, item) => acc + item.qty, 0);
            document.getElementById('header-cart-count').innerText = count;
        }
    },

    /**
     * @namespace App.Catalog
     * @description Handles Product Rendering and Virtual Scrolling
     */
    Catalog: {
        init: () => {
            App.Catalog.observer = new IntersectionObserver((entries) => {
                if (entries[0].isIntersecting) {
                    App.Catalog.renderBatch();
                }
            }, { rootMargin: '100px' });

            App.Catalog.observer.observe(document.getElementById('scroll-sentinel'));
        },

        renderBatch: () => {
            const nextBatch = App.State.products.slice(App.State.displayed, App.State.displayed + App.State.batchSize);
            if (nextBatch.length === 0) {
                document.getElementById('scroll-sentinel').classList.add('hide');
                return;
            }

            const grid = document.getElementById('catalog-grid');

            nextBatch.forEach((product, idxOffset) => {
                const globalIndex = App.State.displayed + idxOffset;
                const altImg = product.altUrl ? `data-alt-src="${product.altUrl}"` : '';
                const stockBadge = product.stock === 0 
                    ? `<span class="badge bg-sold-out badge-stock">SOLD OUT</span>` 
                    : (product.stock < 5 ? `<span class="badge bg-low-stock badge-stock">LOW STOCK</span>` : '');

                const card = document.createElement('div');
                card.className = 'card-product';
                card.innerHTML = `
                    ${stockBadge}
                    <div class="card-img-wrapper cursor-pointer" onclick="App.QuickView.open(${globalIndex})">
                        <img src="${product.image}" ${altImg} alt="${App.Utils.safeStr(product.title)}" data-index="${globalIndex}" />
                    </div>
                    <div class="p-3">
                        <div class="text-uppercase small text-muted mb-1">${App.Utils.safeStr(product.category)}</div>
                        <h5 class="fw-bold mb-2 text-truncate-2 cursor-pointer" onclick="App.QuickView.open(${globalIndex})">${App.Utils.safeStr(product.title)}</h5>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="fw-bold">${App.Utils.formatCurrency(product.price)}</span>
                            <div class="card-actions d-flex" style="position:relative; bottom:auto; padding:0; background:none;">
                                <button class="btn btn-sm btn-outline-dark border-0" onclick="App.Wishlist.toggle(${globalIndex}, this)">
                                    <i class="bi bi-heart"></i>
                                </button>
                                <button class="btn btn-sm btn-dark btn-add-cart" ${product.stock === 0 ? 'disabled' : ''} onclick="App.Cart.add(${globalIndex}, this)">
                                    ADD
                                </button>
                            </div>
                        </div>
                    </div>
                `;
                grid.appendChild(card);

                // Attach Image Swap Event
                const img = card.querySelector('img');
                if (product.altUrl) {
                    img.parentElement.addEventListener('mouseenter', () => img.src = product.altUrl);
                    img.parentElement.addEventListener('mouseleave', () => img.src = product.image);
                }
            });

            App.State.displayed += nextBatch.length;
        }
    },

    /**
     * @namespace App.Cart
     * @description Cart Logic
     */
    Cart: {
        add: (index, btnElement) => {
            const product = App.State.products[index];

            // Check stock
            const inCart = App.State.cart.find(i => i.id === product.id);
            const currentQty = inCart ? inCart.qty : 0;

            if (currentQty >= product.stock) {
                App.UI.toast('Sorry, max stock reached.', 'error');
                return;
            }

            // Animation
            const img = document.querySelector(`img[data-index="${index}"]`);
            App.UI.flyToCart(img);

            // Logic
            if (inCart) {
                inCart.qty++;
            } else {
                App.State.cart.push({ ...product, qty: 1, variant: 'S' }); // Default variant
            }

            App.Cart.render();
            App.UI.toast(`Added ${product.title} to cart`);
        },

        remove: (idx) => {
            App.State.cart.splice(idx, 1);
            App.Cart.render();
        },

        clear: () => {
            App.State.cart = [];
            App.Cart.render();
        },

        render: () => {
            const container = document.getElementById('cart-items-container');
            const totalEl = document.getElementById('cart-total-display');

            if (App.State.cart.length === 0) {
                container.innerHTML = '<div class="text-center text-muted mt-5">Your cart is empty.</div>';
                totalEl.innerHTML = '<span>Total</span><span>$0.00</span>';
                return;
            }

            let html = '';
            let total = 0;

            App.State.cart.forEach((item, idx) => {
                const itemTotal = item.price * item.qty;
                total += itemTotal;
                html += `
                    <div class="d-flex gap-3 mb-3 align-items-center">
                        <img src="${item.image}" style="width: 60px; height: 80px; object-fit: cover;" />
                        <div class="flex-grow-1">
                            <h6 class="mb-0 small fw-bold text-truncate">${App.Utils.safeStr(item.title)}</h6>
                            <div class="small text-muted">${item.variant} | ${App.Utils.formatCurrency(item.price)}</div>
                        </div>
                        <div class="d-flex flex-column align-items-end gap-1">
                            <button class="btn btn-sm text-danger p-0" onclick="App.Cart.remove(${idx})"><i class="bi bi-trash"></i></button>
                            <span class="small fw-bold">x${item.qty}</span>
                        </div>
                    </div>
                `;
            });

            container.innerHTML = html;
            totalEl.innerHTML = `<span>Total</span><span>${App.Utils.formatCurrency(total)}</span>`;
        }
    },

    /**
     * @namespace App.QuickView
     * @description Quick View Modal Logic
     */
    QuickView: {
        modal: null,

        open: (index) => {
            const product = App.State.products[index];
            App.State.currentProduct = product;

            if (!App.QuickView.modal) App.QuickView.modal = new bootstrap.Modal(document.getElementById('quickViewModal'));

            // Populate UI
            document.getElementById('qv-img').src = product.image;
            document.getElementById('qv-cat').innerText = product.category;
            document.getElementById('qv-title').innerText = product.title;
            document.getElementById('qv-price').innerText = App.Utils.formatCurrency(product.price);
            document.getElementById('qv-desc').innerText = product.description || "Premium fashion item from the Aji Shop Casa collection.";

            // Variants (Size Multipliers)
            const variants = [
                { name: 'S', mult: 1.0 },
                { name: 'M', mult: 1.0 },
                { name: 'L', mult: 1.1 }, // Clothes Logic: Larger sizes often cost more
                { name: 'XL', mult: 1.2 }
            ];

            const vContainer = document.getElementById('qv-variants');
            vContainer.innerHTML = variants.map((v, i) => 
                `<button class="btn btn-sm btn-outline-secondary ${i===0?'active':''}" onclick="App.QuickView.selectVariant(this, ${v.mult}, '${v.name}')">${v.name}</button>`
            ).join('');

            // Stock Logic
            const stockMsg = document.getElementById('qv-stock-msg');
            const addBtn = document.getElementById('qv-add-btn');
            if (product.stock === 0) {
                stockMsg.innerHTML = '<span class="text-danger">Sold Out</span>';
                addBtn.disabled = true;
            } else if (product.stock < 5) {
                stockMsg.innerHTML = `<span class="text-warning">Only ${product.stock} left!</span>`;
                addBtn.disabled = false;
            } else {
                stockMsg.innerHTML = '<span class="text-success">In Stock</span>';
                addBtn.disabled = false;
            }

            // Related Products (Simple category match)
            const related = App.State.products
                .filter(p => p.category === product.category && p.id !== product.id)
                .slice(0, 2);

            const rContainer = document.getElementById('qv-related');
            rContainer.innerHTML = related.map(p => `
                <div class="cursor-pointer" onclick="App.QuickView.open(${App.State.products.indexOf(p)})">
                    <img src="${p.image}" style="width: 60px; height: 60px; object-fit: cover; border-radius: 4px;">
                </div>
            `).join('');

            // Inject SEO
            App.Seo.injectSchema(product);

            App.QuickView.modal.show();
        },

        selectVariant: (btn, multiplier, name) => {
            document.querySelectorAll('#qv-variants .btn').forEach(b => b.classList.remove('active', 'btn-dark'));
            document.querySelectorAll('#qv-variants .btn').forEach(b => b.classList.add('btn-outline-secondary'));

            btn.classList.remove('btn-outline-secondary');
            btn.classList.add('active', 'btn-dark');

            const newPrice = App.State.currentProduct.price * multiplier;
            document.getElementById('qv-price').innerText = App.Utils.formatCurrency(newPrice);
            App.State.currentProduct.selectedVariant = name;
            App.State.currentProduct.finalPrice = newPrice;
        }
    },

    /**
     * @namespace App.Wishlist
     * @description Wishlist Logic
     */
    Wishlist: {
        toggle: (index, btn) => {
            const pos = App.State.wishlist.indexOf(index);
            const icon = btn.querySelector('i');

            if (pos === -1) {
                App.State.wishlist.push(index);
                icon.classList.add('text-danger', 'bi-heart-fill');
                icon.classList.remove('bi-heart');
                App.UI.toast('Added to wishlist');
            } else {
                App.State.wishlist.splice(pos, 1);
                icon.classList.remove('text-danger', 'bi-heart-fill');
                icon.classList.add('bi-heart');
            }
            document.getElementById('header-wish-count').innerText = App.State.wishlist.length;
        },

        clearAll: () => {
            App.State.wishlist = [];
            App.Wishlist.render();
            App.UI.toast('Wishlist cleared', 'error');
        },

        render: () => {
            const grid = document.getElementById('wishlist-grid');
            if(App.State.wishlist.length === 0) {
                grid.innerHTML = '<p class="text-muted">Wishlist is empty.</p>';
                return;
            }

            grid.innerHTML = App.State.wishlist.map(index => {
                const p = App.State.products[index];
                if(!p) return '';
                return `
                    <div class="card-product">
                         <div class="card-img-wrapper">
                            <img src="${p.image}" />
                        </div>
                        <div class="p-3">
                            <h6 class="fw-bold text-truncate">${p.title}</h6>
                            <button class="btn btn-sm btn-dark w-100 mt-2" onclick="App.Cart.add(${index}, this)">ADD TO CART</button>
                        </div>
                    </div>
                `;
            }).join('');
        }
    },

    /**
     * @namespace App.Router
     * @description Simple View Switching
     */
    Router: {
        go: (page) => {
            const main = document.querySelector('main');
            const profile = document.getElementById('page-profile');

            if (page === 'wishlist' || page === 'profile') {
                main.classList.add('hide');
                profile.classList.remove('hide');
                App.Wishlist.render();
                // Trigger tab
                const triggerEl = document.querySelector('button[data-bs-target="#tab-wishlist"]');
                bootstrap.Tab.getInstance(triggerEl)?.show() || new bootstrap.Tab(triggerEl).show();
            } else {
                main.classList.remove('hide');
                profile.classList.add('hide');
            }
            window.scrollTo(0,0);
        }
    },

    /**
     * @namespace API
     * @description Blogger Data Fetching from ajishopcasa.blogspot.com
     */
    API: {
        /**
         * @description Fallback data if Blogger API fails
         */
        getFallbackData: () => {
            const cats = ['Dresses', 'Jackets', 'T-Shirts', 'Jeans'];
            const data = [];
            for(let i=1; i<=5; i++) {
                data.push({
                    id: i,
                    title: `Aji Shop Casa Design ${i}`,
                    description: 'A versatile piece for any wardrobe.',
                    image: `https://picsum.photos/seed/ajishop${i}/500/625.jpg`,
                    altUrl: `https://picsum.photos/seed/ajishop${i}alt/500/625.jpg`,
                    category: cats[i % cats.length],
                    price: (Math.random() * 100 + 20).toFixed(2),
                    stock: i === 1 ? 0 : i
                });
            }
            return data;
        },

        /**
         * @description Parse Blogger JSON Feed with Defensive Checks
         */
        parseCatalog: (json) => {
            try {
                if (!json.feed || !json.feed.entry) throw new Error("No entries");

                const products = json.feed.entry.map((entry) => {
                    // Defensive Checks for Title
                    const title = (entry.title && entry.title.$t) ? entry.title.$t : "Untitled Product";

                    // Defensive Checks for Content/Summary
                    let content = "";
                    if (entry.content && entry.content.$t) {
                        content = entry.content.$t;
                    } else if (entry.summary && entry.summary.$t) {
                        content = entry.summary.$t;
                    }

                    // Defensive Checks for Labels
                    const labels = (entry.category && Array.isArray(entry.category)) ? entry.category.map(c => c.term) : [];

                    // Defensive Image Extraction
                    // 1. Try to find img src in content
                    const imgMatch = content.match(/src="([^"]+)"/);
                    let img = imgMatch ? imgMatch[1] : null;

                    // 2. Fallback to media$thumbnail (Blogger default)
                    if (!img && entry.media$thumbnail) {
                        img = entry.media$thumbnail.url;
                    }

                    // 3. Fallback to Placeholder
                    if (!img) {
                        img = App.Utils.getPlaceholder(entry.id.$t, 500, 625);
                    }

                    // Parsing Category & Alt Images
                    const category = labels.find(l => l.startsWith('cat-'))?.replace('cat-', '') || 'General';
                    const altUrl = labels.find(l => l.startsWith('img-alt-url-'))?.replace('img-alt-url-', '');

                    // Stock parsing
                    const stockLabel = labels.find(l => l.startsWith('stock-'));
                    const stock = stockLabel ? parseInt(stockLabel.replace('stock-', '')) : 100;

                    return {
                        id: entry.id.$t,
                        title: title,
                        image: img,
                        altUrl: altUrl || null,
                        category: category,
                        description: content.replace(/<[^>]*>?/gm, '').substring(0, 100), // Strip HTML for desc
                        price: 49.99, // Base price
                        stock: stock
                    };
                });

                App.State.products = products;
                App.Catalog.renderBatch();

                // Remove skeletons from filter bar
                const uniqueCats = [...new Set(products.map(p => p.category))];
                document.getElementById('filter-container').innerHTML = `
                    <div class="d-flex gap-2 overflow-auto pb-2">
                        <button class="btn btn-sm btn-dark rounded-pill px-3">All</button>
                        ${uniqueCats.map(c => 
                            `<button class="btn btn-sm btn-outline-secondary rounded-pill px-3">${c}</button>`
                        ).join('')}
                    </div>
                `;

            } catch (e) {
                console.warn("Blogger API Error, using fallback", e);
                App.State.products = App.API.getFallbackData();
                App.Catalog.renderBatch();
            }
        }
    },

    /**
     * @description Initialization
     */
    init: () => {
        AOS.init();
        App.Catalog.init();

        // Load feed from ajishopcasa.blogspot.com
        const script = document.createElement('script');
        script.src = 'https://ajishopcasa.blogspot.com/feeds/posts/default?alt=json-in-script&callback=App.API.parseCatalog&max-results=500';

        script.onerror = () => {
            App.API.parseCatalog({ feed: { entry: [] } });
        };

        // Fallback in case feed never loads or fails
        setTimeout(() => {
            if(App.State.products.length === 0) {
                 App.API.parseCatalog({ feed: { entry: [] } });
            }
        }, 3000);

        document.body.appendChild(script);
    }
};

// Start App
document.addEventListener('DOMContentLoaded', App.init);

//
